{
  "statements": [
    {
      "id": "1a",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT changing position on the road involves changing lanes or passing another vehicle",
      "sources": [
        {
          "id": "m1",
          "quote": "Changing your position on the road involves changing lanes or overtaking and passing another vehicle."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "1b",
      "type": "DEFINE",
      "force": null,
      "force_from": null,
      "text": "DEFINE passing IS changing lanes THAT moves past a slower vehicle",
      "sources": [
        {
          "id": "m2",
          "quote": "Passing is changing lanes to move past a slower vehicle."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "1c",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT not all vehicles travel at the same speed",
      "sources": [
        {
          "id": "m3",
          "quote": "While all public roads have speed limits, not all vehicles travel at the same speed."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "1d",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT cyclists, road service vehicles and drivers ahead preparing to turn are [?usually] slower than through traffic",
      "sources": [
        {
          "id": "m3",
          "quote": "For example, cyclists, road service vehicles and drivers ahead that are preparing to turn are usually slower than the through traffic."
        }
      ],
      "flags": [
        {
          "code": "S",
          "span": "usually",
          "note": "Hedged scope; the handbook does not say how often."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "1e",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a driver may want to pass [?some] slow-moving vehicles when following them",
      "sources": [
        {
          "id": "m3",
          "quote": "You may want to pass some slow-moving vehicles when you are following them."
        }
      ],
      "flags": [
        {
          "code": "S",
          "span": "some",
          "note": "Hedged quantity; no number is given."
        }
      ],
      "links": [],
      "note": "\"May want\" expresses a possibility or desire, not a permission, so this is a FACT."
    },
    {
      "id": "2.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"be sure\")",
      "text": "a driver SHOULD be [?sure] the driver has [?enough] space and time to complete a lane change or pass a vehicle [?safely] WHEN the driver is about to change lanes or pass a vehicle",
      "sources": [
        {
          "id": "m4",
          "quote": "Before beginning, be sure you have enough space and time to complete the move safely."
        },
        {
          "id": "m1",
          "quote": "Changing your position on the road involves changing lanes or overtaking and passing another vehicle."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "sure",
          "note": "Subjective certainty; no observable test."
        },
        {
          "code": "J",
          "span": "enough",
          "note": "No measure of space or time."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "No stated safety criterion."
        }
      ],
      "links": [],
      "note": "\"The move\" is read from m1 as changing lanes or passing a vehicle."
    },
    {
      "id": "2.1b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Never\")",
      "text": "a driver SHOULD NOT pass a vehicle UNLESS the driver is [?sure] the driver can pass without [?danger] to the driver or other road users",
      "sources": [
        {
          "id": "m5",
          "quote": "Never overtake and pass another vehicle unless you are sure you can do so without danger to yourself or others."
        }
      ],
      "flags": [
        {
          "code": "M",
          "span": "Never",
          "note": "An absolute with no legal wording, so the force remains advisory."
        },
        {
          "code": "J",
          "span": "sure",
          "note": "Subjective certainty; no observable test."
        },
        {
          "code": "J",
          "span": "danger",
          "note": "Subjective hazard; no stated criterion."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "2.1c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not\")",
      "text": "a driver SHOULD NOT pass WHEN the driver is [?in doubt]",
      "sources": [
        {
          "id": "m6",
          "quote": "If in doubt, do not pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "in doubt",
          "note": "Subjective state; no observable test."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "2.2a",
      "type": "PROCEDURE",
      "force": "ADVISORY",
      "force_from": "imperative steps",
      "text": "TO pass a vehicle",
      "steps": [
        {
          "n": "1",
          "text": "use the left-turn signal to show the driver wants to pass AND check that the way is [?clear] ahead and behind WHEN the driver is about to move into the passing lane",
          "sources": [
            "m9"
          ]
        },
        {
          "n": "2",
          "text": "WATCH FOR bicycles and small vehicles that may be hidden from view in front of the vehicle being passed AND vehicles that may be turning left in front of the driver AND vehicles or pedestrians entering the road from another road or driveway",
          "sources": [
            "m10"
          ]
        },
        {
          "n": "3",
          "text": "change lanes into the passing lane ONLY IF the driver has signalled",
          "sources": [
            "m11"
          ]
        },
        {
          "n": "4",
          "text": "signal that the driver wants to move back into the original lane WHEN the driver has passed the vehicle being passed",
          "sources": [
            "m11"
          ]
        },
        {
          "n": "5",
          "text": "change lanes into the original lane WHEN the driver can see the entire front of the vehicle being passed in the inside mirror",
          "sources": [
            "m11"
          ]
        },
        {
          "n": "IF",
          "text": "IF the vehicle being passed speeds up THEN do not race AND go back into the original lane",
          "sources": [
            "m13"
          ]
        }
      ],
      "sources": [
        {
          "id": "m8",
          "quote": "Here are the steps for passing a vehicle:"
        },
        {
          "id": "m14",
          "quote": "how to pass another vehicle"
        },
        {
          "id": "m52",
          "quote": "how to pass another vehicle"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "clear",
          "note": "No standard for how clear the way must be."
        },
        {
          "code": "V",
          "span": "rear view mirror",
          "note": "m43 calls the inside mirror a rear view mirror."
        }
      ],
      "links": [],
      "note": "m14 and m52 both illustrate the passing procedure."
    },
    {
      "id": "2.2b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "caution (\"Be careful not to\")",
      "text": "a driver SHOULD NOT cut off a vehicle by [?suddenly] moving in front of it WHILE passing",
      "sources": [
        {
          "id": "m12",
          "quote": "Be careful not to cut off a vehicle by suddenly moving in front of it."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "suddenly",
          "note": "Abruptness has no stated standard."
        }
      ],
      "links": [
        "2.2a"
      ],
      "note": "The condition comes from the heading \"Passing\"."
    },
    {
      "id": "2.3a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"make\")",
      "text": "a driver SHOULD change lanes into the original lane WHEN the driver is passing a vehicle AND the driver can see the entire front of the vehicle being passed in the inside mirror",
      "sources": [
        {
          "id": "m11",
          "quote": "Change lanes only after signalling. After overtaking, signal that you want to move back into the lane you started from, and when you can see the entire front of the vehicle you are passing in your inside mirror, make the lane change."
        }
      ],
      "flags": [
        {
          "code": "V",
          "span": "rear view mirror",
          "note": "m43 calls the inside mirror a rear view mirror."
        }
      ],
      "links": [
        "2.2a"
      ],
      "note": "Taken from the passing procedure; it states the condition for returning to the original lane."
    },
    {
      "id": "3.1.1a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not permitted\")",
      "text": "a driver MUST NOT pass a vehicle WHEN the driver is within 30 m of a pedestrian crossover",
      "sources": [
        {
          "id": "m15",
          "quote": "Passing within 30 metres of a pedestrian crossover is not permitted."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.1.2a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not permitted\")",
      "text": "a driver MUST NOT pass left of a centreline WHEN the driver is within 30 m of a bridge, viaduct or tunnel",
      "sources": [
        {
          "id": "m17",
          "quote": "Passing left of a centreline is not permitted 30 metres from a bridge, viaduct or tunnel."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.1.3a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Don't\")",
      "text": "a driver SHOULD NOT attempt to pass WHEN (the driver is approaching the crest of a hill OR the driver is on a curve) AND the driver's view of oncoming traffic is obstructed AND there is not [?enough clear] distance ahead to pass [?in safety]",
      "sources": [
        {
          "id": "m18",
          "quote": "Don't attempt to pass when approaching the crest of a hill or on a curve where your vision of oncoming traffic is obstructed and there is not enough clear distance ahead to pass in safety."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough clear",
          "note": "No measure of distance or clarity."
        },
        {
          "code": "J",
          "span": "in safety",
          "note": "No stated safety criterion."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.1a",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT [?some] roads have special passing or climbing lanes that let slower vehicles move into the right-hand lane so that faster vehicles can pass [?safely] in the left lane",
      "sources": [
        {
          "id": "m28",
          "quote": "Some roads have special passing or climbing lanes. These lanes let slower vehicles move into the right-hand lane so that faster ones can pass safely in the left lane."
        },
        {
          "id": "m27",
          "quote": "a passing or climbing lane"
        }
      ],
      "flags": [
        {
          "code": "S",
          "span": "some",
          "note": "Hedged scope; not all roads are covered."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "No stated safety criterion."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.1b",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT an advance sign tells a driver that the driver will soon have a chance to pass a vehicle",
      "sources": [
        {
          "id": "m29",
          "quote": "An advance sign tells drivers they will soon have a chance to pass."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.1c",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a sign warns a driver that the passing or climbing lane is ending BECAUSE the sign lets drivers in the right-hand lane begin to merge [?safely] with traffic in the left-hand lane",
      "sources": [
        {
          "id": "m29",
          "quote": "Another sign warns when the lane is ending so drivers in the right-hand lane can begin to merge safely with traffic in the left-hand lane."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safely",
          "note": "No stated safety criterion."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3a",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT [?most] passing is done on the left",
      "sources": [
        {
          "id": "m35",
          "quote": "Most passing is done on the left."
        }
      ],
      "flags": [
        {
          "code": "S",
          "span": "most",
          "note": "Hedged scope; not all passing is covered."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3b",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may\")",
      "text": "a driver MAY pass on the right WHEN the road is multi-lane OR the road is one-way OR the driver is passing a streetcar OR the driver is passing a left-turning vehicle",
      "sources": [
        {
          "id": "m35",
          "quote": "You may pass on the right on multi-lane or one-way roads and when overtaking a streetcar or a left-turning vehicle."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3c",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT passing on the right can be more dangerous than passing on the left",
      "sources": [
        {
          "id": "m36",
          "quote": "Passing on the right can be more dangerous than passing on the left."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3d",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"wait\")",
      "text": "a driver SHOULD wait WHEN the driver is driving in the far-left lane AND a slower vehicle is in front of the driver UNTIL the slower vehicle moves to the right",
      "sources": [
        {
          "id": "m37",
          "quote": "If you are driving in the left most lane with a slower vehicle in front of you, wait for the vehicle to move to the right."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3e",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not\")",
      "text": "a driver SHOULD NOT [?suddenly] change lanes and pass on the right WHEN the driver is driving in the far-left lane AND a slower vehicle is in front of the driver BECAUSE the slower vehicle may realize the driver wants to pass and move to the right at the same time",
      "sources": [
        {
          "id": "m37",
          "quote": "Do not suddenly change lanes and pass on the right; the driver in front may realize you want to pass and move to the right at the same time you do."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "suddenly",
          "note": "Abruptness has no stated standard."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.4a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may drive\")",
      "text": "a driver MAY drive on the right shoulder ONLY IF the driver is passing a vehicle turning left AND the shoulder is paved",
      "sources": [
        {
          "id": "m38",
          "quote": "You may drive on the right shoulder only to pass a vehicle turning left and only if the shoulder is paved."
        }
      ],
      "flags": [
        {
          "code": "D",
          "span": "only to pass",
          "note": "The permission presupposes that driving on the right shoulder is otherwise not allowed."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.4b",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may not\")",
      "text": "a driver MUST NOT pass on the left shoulder, paved or not",
      "sources": [
        {
          "id": "m38",
          "quote": "You may not pass on the left shoulder, paved or not."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.3.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "caution (\"Be very careful\")",
      "text": "a driver SHOULD drive with [?extra care] WHILE passing a vehicle at night",
      "sources": [
        {
          "id": "m39",
          "quote": "Be very careful when you pass other vehicles at night."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "extra care",
          "note": "Added for \"be very careful\", which names no specific hazard."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.3.1b",
      "type": "PROCEDURE",
      "force": "ADVISORY",
      "force_from": "imperative steps",
      "text": "TO pass a vehicle at night SPECIALIZES 2.2a WHEN the driver has to pass AND the way is [?clear]",
      "steps": [
        {
          "n": "1",
          "text": "switch the headlights to low beams WHEN the driver is approaching a vehicle from behind",
          "sources": [
            "m41"
          ]
        },
        {
          "n": "2",
          "text": "signal AND check the mirrors and blind spot AND pull out to pass",
          "sources": [
            "m42"
          ]
        },
        {
          "n": "3",
          "text": "switch on the high beams WHILE the driver moves alongside the vehicle being passed BECAUSE this lets the driver see more of the road ahead",
          "sources": [
            "m42"
          ]
        },
        {
          "n": "4",
          "text": "signal AND pull back into the right-hand lane WHEN the driver can see all of the front of the vehicle being passed in the inside mirror",
          "sources": [
            "m43"
          ]
        }
      ],
      "sources": [
        {
          "id": "m40",
          "quote": "If you have to pass and the way is clear, follow these steps:"
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "clear",
          "note": "No standard for how clear the way must be."
        },
        {
          "code": "V",
          "span": "rear view mirror",
          "note": "m43 calls the inside mirror a rear view mirror."
        }
      ],
      "links": [
        "2.2a"
      ],
      "note": "The lead sentence gives the condition; the procedure specializes the general passing procedure."
    },
    {
      "id": "3.4.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "caution (\"watch\")",
      "text": "a driver SHOULD WATCH FOR people suddenly opening doors OR doors opened to load and unload WHILE passing parked vehicles",
      "sources": [
        {
          "id": "m50",
          "quote": "When passing parked vehicles, watch carefully for people suddenly opening doors or for doors opened to load and unload."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "carefully",
          "note": "\"Carefully\" is a judgment term and was not repeated in the statement."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.2a",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT motorcycles, bicycles, limited-speed motorcycles and mopeds [?often] need to pull to the left or right side of their lane to avoid dangerous road conditions or to be seen by other drivers",
      "sources": [
        {
          "id": "m51",
          "quote": "Motorcycles, bicycles, limited-speed motorcycles and mopeds often need to pull to the left or right side of their lane to avoid dangerous road conditions or to be seen by other drivers."
        }
      ],
      "flags": [
        {
          "code": "S",
          "span": "often",
          "note": "Hedged frequency; no standard is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.2b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not take\")",
      "text": "a driver SHOULD NOT pass a motorcycle, a bicycle, a limited-speed motorcycle or a moped in the same lane WHEN the vehicle pulls to the left or right side of its lane",
      "sources": [
        {
          "id": "m51",
          "quote": "Motorcycles, bicycles, limited-speed motorcycles and mopeds often need to pull to the left or right side of their lane to avoid dangerous road conditions or to be seen by other drivers. Do not take this as an invitation to pass in the same lane."
        }
      ],
      "flags": [],
      "links": [],
      "note": "\"This\" is resolved to the pulling to the side described in m51."
    },
    {
      "id": "3.4.2c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do so\")",
      "text": "a driver SHOULD change lanes to pass a motorcycle, a bicycle, a limited-speed motorcycle or a moped WHEN the driver wants to pass the vehicle",
      "sources": [
        {
          "id": "m51",
          "quote": "If you do want to pass these vehicles, do so by changing lanes."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.5a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"must\")",
      "text": "a driver MUST pass a streetcar on the right UNLESS the road is one-way",
      "sources": [
        {
          "id": "m62",
          "quote": "You must pass streetcars on the right unless you are driving on a one-way road."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.5b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"stay\")",
      "text": "a driver SHOULD stay at least 2 m behind the rear doors of a stopped streetcar WHEN the driver is at a streetcar stop AND passengers are getting off or on UNLESS the streetcar stop has an area set aside for streetcar passengers",
      "sources": [
        {
          "id": "m63",
          "quote": "At streetcar stops, stay at least two metres behind the rear doors where passengers are getting off or on. This rule does not apply at stops where an area has been set aside for streetcar passengers."
        },
        {
          "id": "m61",
          "quote": "a vehicle stopped the required two metres behind the rear doors of a stopped streetcar"
        }
      ],
      "flags": [
        {
          "code": "M",
          "span": "stay at least two metres",
          "note": "A fixed distance in a bare imperative reads like a duty, but the passage has no direct legal wording."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.5c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Always\")",
      "text": "a driver SHOULD pass [?these areas] at [?reasonable] speed AND WATCH FOR pedestrians making sudden or unexpected moves WHEN passing a streetcar stop",
      "sources": [
        {
          "id": "m64",
          "quote": "Always pass these areas at a reasonable speed and be prepared for pedestrians to make sudden or unexpected moves."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "these areas",
          "note": "Unclear whether these are all streetcar stop areas or only set-aside passenger areas."
        },
        {
          "code": "J",
          "span": "reasonable",
          "note": "No stated speed standard."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.9a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Don't\")",
      "text": "a driver SHOULD NOT pass a moving snow plow under any conditions",
      "sources": [
        {
          "id": "m72",
          "quote": "Don't pass moving snow plows under any conditions."
        }
